    fun fetchDependencies(dependencyId: DependencyId): Dependency =
        runBlocking(Dispatchers.IO) {
            // 병렬 비동기 호출로 성능 최적화
            val categoriesDeferred = async {
                if (dependencyId.categoryIds.isEmpty()) {
                    emptyMap()
                } else {
                    categoryService.getCategories(dependencyId.categoryIds)
                        .associateBy { it.id }
                }
            }
            val brandsDeferred = async {
                if (dependencyId.brandIds.isEmpty()) {
                    emptyMap()
                } else {
                    brandService.getBrands(dependencyId.brandIds)
                        .associateBy { it.id }
                }
            }
            val manufacturersDeferred = async {
                if (dependencyId.manufacturerIds.isEmpty()) {
                    emptyMap()
                } else {
                    manufacturerService.getManufacturers(dependencyId.manufacturerIds)
                        .associateBy { it.id }
                }
            }
            val mallsDeferred = async {
                if (dependencyId.mallIds.isEmpty()) {
                    emptyMap()
                } else {
                    mallService.getMalls(dependencyId.mallIds)
                        .associateBy { it.mallId }
                }
            }

            Dependency(
                categories = categoriesDeferred.await(),
                brands = brandsDeferred.await(),
                manufacturers = manufacturersDeferred.await(),
                malls = mallsDeferred.await(),
            )
        }
}
```

